const localResults = $('Google Search — Local').first().json;
const intlResults = $('Google Search — International').first().json;
const existing = $('Sheets — Articles existants').all().map(i => i.json);

const localItems = (localResults?.items || []).map(i => ({ title: i.title, snippet: i.snippet, url: i.link }));
const intlItems = (intlResults?.items || []).map(i => ({ title: i.title, snippet: i.snippet, url: i.link }));
const existingTitles = existing.map(e => e.Titre_SEO || '').filter(Boolean);

return [{
  json: {
    local_search_results: localItems,
    international_results: intlItems,
    existing_articles: existingTitles
  }
}];

const response = $input.first().json;
const today = new Date().toISOString().split('T')[0];

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing réponse Gemini: ' + e.message);
}

const articles = (parsed.articles || []).map(a => ({
  Date: today,
  Titre_SEO: a.title_seo,
  Mot_Cle: a.main_keyword,
  Angle_Local: a.local_angle,
  Volume_Estime: a.competition_level,
  Score: a.seo_potential_score,
  Status: 'nouveau',
  Meta_Description: a.meta_description,
  Keywords_Secondaires: (a.secondary_keywords || []).join(', '),
  Structure: (a.suggested_structure || []).join(' | '),
  Longueur_Recommandee: a.recommended_length,
  Intent: a.search_intent,
  Content_Gap: a.content_gap
}));

return articles.map(a => ({ json: a }));
